CREATE TABLE workflow_definition(tenant text NOT NULL,name text NOT NULL,version integer NOT NULL,hash text NOT NULL,body text NOT NULL,PRIMARY KEY(tenant,name,version),UNIQUE(tenant,hash));
CREATE TABLE workflow_instance(id uuid PRIMARY KEY,tenant text NOT NULL,definition_hash text NOT NULL,semantics text NOT NULL,input text NOT NULL,start_key text NOT NULL,request_hash text NOT NULL,state text NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant,start_key));
CREATE INDEX instance_tenant ON workflow_instance(tenant,id);
CREATE TABLE workflow_history(instance_id uuid REFERENCES workflow_instance(id),sequence bigint NOT NULL,type text NOT NULL,task text NOT NULL,value text NOT NULL,at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(instance_id,sequence));
CREATE TABLE activity_task(instance_id uuid REFERENCES workflow_instance(id),logical_id text NOT NULL,activity text NOT NULL,safety text NOT NULL,parameters text NOT NULL,status text NOT NULL,generation bigint NOT NULL DEFAULT 0,attempt integer NOT NULL DEFAULT 0,worker text,credential text,lease_until timestamptz,due_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),dispatch_intent boolean NOT NULL DEFAULT false,PRIMARY KEY(instance_id,logical_id));
CREATE INDEX task_ready ON activity_task(status,due_at);
CREATE TABLE activity_attempt(instance_id uuid NOT NULL,logical_id text NOT NULL,generation bigint NOT NULL,worker text NOT NULL,dispatched_at timestamptz,completed_at timestamptz,outcome text,PRIMARY KEY(instance_id,logical_id,generation));
CREATE TABLE timer(instance_id uuid REFERENCES workflow_instance(id),logical_id text NOT NULL,due_at timestamptz NOT NULL,status text NOT NULL,PRIMARY KEY(instance_id,logical_id));
CREATE INDEX timer_due ON timer(status,due_at);
CREATE TABLE signal_inbox(instance_id uuid REFERENCES workflow_instance(id),request_key text NOT NULL,signal text NOT NULL,payload text NOT NULL,accepted boolean NOT NULL,at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(instance_id,request_key));
CREATE TABLE compensation_obligation(instance_id uuid REFERENCES workflow_instance(id),logical_id text NOT NULL,activity text NOT NULL,completion_sequence bigint NOT NULL,status text NOT NULL DEFAULT 'PENDING',PRIMARY KEY(instance_id,logical_id));
CREATE TABLE operator_decision(instance_id uuid REFERENCES workflow_instance(id),sequence bigint NOT NULL,operator_id text NOT NULL,task text NOT NULL,resolution text NOT NULL,reason text NOT NULL,PRIMARY KEY(instance_id,sequence));
